"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["37574"],{52106(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.sem_destinos","status":422,"titulo":"A cascata precisa de ao menos um destino"},"descricao":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.sem_destinos","requisitos":["UNI-REQ-0056"],"oQueAconteceu":["A lista `destinos` do corpo do pedido de defini\xe7\xe3o da cascata veio vazia. Uma\\ncascata sem nenhuma posi\xe7\xe3o n\xe3o tem fila de remanejamento nenhuma \u2014 s\xf3 o\\nfallback, que sozinho n\xe3o \xe9 uma cascata (se a inten\xe7\xe3o era n\xe3o configurar\\ncascata nenhuma, a opera\xe7\xe3o correta \xe9 remover a configura\xe7\xe3o, n\xe3o enviar\\numa lista vazia).","S\xf3 pode coexistir, na mesma resposta, com\\n[`fallback_obrigatorio`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.fallback_obrigatorio)\\n\u2014 com a lista vazia, n\xe3o h\xe1 origem alguma para as demais confer\xeancias desta\\ns\xe9rie (limite de origens/destinos, ordem, destino repetido) conferirem;\\nnenhuma delas dispara."],"comoResolver":["Envie ao menos uma posi\xe7\xe3o em `destinos`. Se a inten\xe7\xe3o era remover a\\ncascata configurada, envie os quatro campos (`regraCodigo`, `regraVersao`,\\n`fallbackCodigo`, `destinos`) como ausentes, em vez de uma lista vazia."],"ondeAparece":["Defini\xe7\xe3o de cascata de remanejamento do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao cascata remanejamento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);